-- Check for international flows (different origin and destination)
SELECT COUNT(*) as total, COUNT(CASE WHEN orignation != destnation THEN 1 END) as intl_flows
FROM dataflow;

-- Check the range of days_overdue
SELECT MIN(CURRENT_DATE - a.remeddue) as min_days, MAX(CURRENT_DATE - a.remeddue) as max_days
FROM auditandcompliance a;

-- Check if auditandcompliance and dataflow have direct relationship or need riskmanagement
SELECT COUNT(*) FROM dataflow d 
JOIN auditandcompliance a ON d.recordregistry = a.recordregistry;
